+++ b/sql/auth/sql_auth_cache.cc
@@ -1961,7 +1961,6 @@ static bool acl_load(THD *thd, Table_ref *tables) {
     LogErr(WARNING_LEVEL, ER_MISSING_GRANT_SYSTEM_TABLE);
   }

-  initialized = true;
   return_val = false;

 end:
@@ -2596,6 +2595,7 @@ static bool grant_load(THD *thd, Table_ref *tables) {
   t_table->file->ha_index_end();
 end_index_init:
   thd->variables.sql_mode = old_sql_mode;
+  if (!return_val) initialized = true;
   return return_val;
 }

@@ -2652,6 +2652,8 @@ static bool grant_reload_procs_priv(Table_ref *table) {
 */

 bool grant_reload(THD *thd, bool mdl_locked) {
+  DBUG_EXECUTE_IF("enable_debug_sync_before_grant_reload",
+                  { DEBUG_SYNC(thd, "before_grant_reload"); };);
   MEM_ROOT old_mem;
   bool return_val = true;
   const uint flags = mdl_locked
@@ -2663,9 +2665,6 @@ bool grant_reload(THD *thd, bool mdl_locked) {

   DBUG_TRACE;

-  /* Don't do anything if running with --skip-grant-tables */
-  if (!initialized) return false;
-
   thd->variables.sql_mode &= ~MODE_PAD_CHAR_TO_FULL_LENGTH;

   Table_ref tables[3] = {
diff --git a/sql/auth/sql_auth_cache.h b/sql/auth/sql_auth_cache.h
index d2d81d8cdadb..a079d3131397 100644
--- a/sql/auth/sql_auth_cache.h
+++ b/sql/auth/sql_auth_cache.h
@@ -23,6 +23,7 @@
 #ifndef SQL_USER_CACHE_INCLUDED
 #define SQL_USER_CACHE_INCLUDED

+#include <assert.h>
 #include <string.h>
 #include <sys/types.h>
 #include <atomic>
@@ -566,6 +567,7 @@ inline GRANT_NAME *routine_hash_search(const char *host, const char *ip,
                                        const char *db, const char *user,
                                        const char *tname, bool proc,
                                        bool exact) {
+  assert(proc ? proc_priv_hash : func_priv_hash);
   return name_hash_search(proc ? *proc_priv_hash : *func_priv_hash, host, ip,
                           db, user, tname, exact, true);
 }
@@ -573,6 +575,7 @@ inline GRANT_NAME *routine_hash_search(const char *host, const char *ip,
 inline GRANT_TABLE *table_hash_search(const char *host, const char *ip,
                                       const char *db, const char *user,
                                       const char *tname, bool exact) {
+  assert(column_priv_hash);
   return name_hash_search(*column_priv_hash, host, ip, db, user, tname, exact,
                           false);
 }
diff --git a/sql/auth/sql_authorization.cc b/sql/auth/sql_authorization.cc
index f96fab431cad..022cbb6ea98b 100644
--- a/sql/auth/sql_authorization.cc
+++ b/sql/auth/sql_authorization.cc
@@ -4439,6 +4439,9 @@ Access_bitmask get_table_grant(THD *thd, Table_ref *table) {
   Security_context *sctx = thd->security_context();
   const char *db = table->db ? table->db : thd->db().str;
   GRANT_TABLE *grant_table;
+
+  if (!initialized) return ALL_ACCESS;
+
   Acl_cache_lock_guard acl_cache_lock(thd, Acl_cache_lock_mode::READ_MODE);

   if (!acl_cache_lock.lock(false)) return (NO_ACCESS);
@@ -4478,6 +4481,9 @@ Access_bitmask get_column_grant(THD *thd, GRANT_INFO *grant,
   GRANT_COLUMN *grant_column;
   Access_bitmask priv;
   Security_context *sctx = thd->security_context();
+
+  if (!initialized) return ALL_ACCESS;
+
   Acl_cache_lock_guard acl_cache_lock(thd, Acl_cache_lock_mode::READ_MODE);

   if (!acl_cache_lock.lock(false)) return (NO_ACCESS);
